 summary['implementation_status_counts']['upstream-adapter-validated']+=1;summary['implementation_status_counts']['existing-adapter']-=1;summary['integration_family_counts'].update(scoped=182,upstream=146,including_existing_adapters=184);summary.update(reviewed_tool_uses=1869,pending_tool_use_reviews=865,current_effective_registry=FOLDER+'/REGISTRY.json')
 after={META[i]:encoded(x)for i,x in[(0,papers),(1,inventory),(2,summary),(7,ledger)]};preface='# Current source-bound WGCNA workflows\n\n'+NOTICE+'\n\n'+SCOPE+'\n\n**Warnings and required actions:** '+ACTION+'\n\nSee [guide](../../wgcna-tools.md), [source roles](../wgcna-source-audit/ROLES.json) and [handover](../wgcna-validation/HANDOVER.md). Earlier checkpoints below are historical.\n\n---\n\n'
 for name in META[3:7]:after[name]=preface.encode()+before[name]
 notice='<aside id="wgcna1721-notice"><h2>Original WGCNA and native components</h2><p>'+html.escape(NOTICE)+'</p><p>'+html.escape(SCOPE)+'</p><p><strong>Warnings and required actions:</strong> '+html.escape(ACTION)+'</p></aside>'
 for name in META[8:]:
  page=before[name].decode();require('id="wgcna1721-notice"'not in page,'Already admitted')
  if name==META[8]:
   match=re.search(r'(<script id="review-data" type="application/json">)(.*?)(</script>)',page,re.S);require(match and json.loads(match[2])==dict(papers=json.loads(before[META[0]]),tools=json.loads(before[META[1]]),summary=json.loads(before[META[2]])),'Prior report payload differs');payload=json.dumps(dict(papers=papers,tools=inventory,summary=summary),ensure_ascii=False).replace('<','\\u003c');page=page[:match.start(2)]+payload+page[match.end(2):]
