 coverage=dict(schema_version=1,scope=SCOPE,required_action=ACTION,roles=roles,new_upstream_family_credit=1,new_source_reviews=5,qualification=Q,source_review=source.FOLDER,exact_author_recipe_qualified=False,whole_goal_complete=False)
