def check(root):
 folder=root/FOLDER;base=read(folder/'BASELINE.json');require(pin(folder/'metadata-before.zip')==base['archive']and pin(folder/'PREVIOUS-SHA256SUMS')==base['previous_checksums']and pin(root/'tools/literature/wgcna_catalog.py')==base['transformer'],'Admission baseline changed');verify(root)
