 with zipfile.ZipFile(folder/'metadata-before.zip')as z:require(set(z.namelist())==set(META),'Baseline family differs');before={n:z.read(n)for n in META}
 require({n:identity(raw)for n,raw in before.items()}==base['metadata'],'Baseline bytes changed');registry=predecessor(root,before);after,registry,coverage=transition(root,before,registry,read(root/Q));require(all((root/n).read_bytes()==raw for n,raw in after.items()),'Current catalog is not exact WGCNA transition');require(read(folder/'REGISTRY.json')==registry and read(root/COVERAGE)==coverage,'Current role registry differs');verify_fixed_cohort(root,root/DATA,json.loads(after[META[0]]))
 previous=checksums((folder/'PREVIOUS-SHA256SUMS').read_bytes());sums=checksums((root/DATA/'SHA256SUMS').read_bytes());require(set(sums)==set(previous)|{Path(COVERAGE).name,Path(PROOF).name},'Checksum family differs');changed={Path(n).name for n in META if n.startswith(DATA+'/')};require(all(sums[n]==v or n in changed for n,v in previous.items()),'Unrelated checksum changed');verify_sums(root,sums);require(read(root/PROOF)==dict(schema_version=1,status='PASS_WGCNA_FORWARD_ADMISSION',totals=totals(),raw_source_text_published=False,literature_pages_published=False),'Admission proof differs');return totals()
