 names=[source.FOLDER+'/'+n for n in['CENSUS.json','ROLES.json','REVIEW-ENTRIES.json']]+['tools/literature/wgcna_source_audit.py'];(folder/'PREVIOUS-SHA256SUMS').write_bytes(previous);(folder/'BASELINE.json').write_bytes(encoded(dict(schema_version=1,archive=pin(folder/'metadata-before.zip'),previous_checksums=pin(folder/'PREVIOUS-SHA256SUMS'),metadata={n:identity(raw)for n,raw in before.items()},transformer=pin(Path(__file__)),source_files={n:pin(root/n)for n in names})));(out/'PLAN.json').write_bytes(encoded(dict(before={n:identity(raw)for n,raw in before.items()},after={n:identity(raw)for n,raw in after.items()},totals=totals())))
 for i,(n,raw)in enumerate(after.items()):require((root/n).read_bytes()==before[n],'Concurrent catalog edits');stage=out/('stage-'+str(i));stage.write_bytes(raw);os.replace(stage,root/n)
